  has_many :questions, -> { order(:position, :id) }, dependent: :destroy
  has_many :active_questions, -> { where(active: true).order(:position, :id) }, class_name: "Question"
  has_many :games, dependent: :destroy

  normalizes :title, with: ->(title) { title.strip }

  validates :title, presence: true
  validates :number_of_winners,
    presence: true,
    numericality: { only_integer: true, greater_than_or_equal_to: 1, allow_blank: true }

  def export_payload
    loaded_questions = questions.includes(:options).to_a
    {
      "title" => title,
      "questions" => loaded_questions.map do |question|
        {
          "text" => question.body,
          "active" => question.active?,
          "options" => question.options.to_a.map do |option|
            {
              "text" => option.text,
              "correct" => option.correct?
            }
          end
        }
      end
    }
  end

  def to_export_json
    JSON.pretty_generate(export_payload)
  end
end
