      this.renderedControlsKey = nextControlsKey
    }
  }

  renderControls(state) {
    const status = state.status
    const question = state.question
    this.actionButtonsTarget.replaceChildren()

    if (status === "lobby") {
      this.appendActionForm(this.startUrlValue, "Start", "btn btn--pink btn--lg")
    } else if (status === "question_open" && question) {
      this.appendActionForm(this.finishUrlValue, "Finish", "btn btn--pink btn--lg")
    } else if (status === "question_closed" && question) {
      if (question.last_question) {
        this.appendActionForm(this.endUrlValue, "End quiz", "btn btn--pink btn--lg")
      } else {
        this.appendActionForm(this.nextUrlValue, "Next", "btn btn--pink btn--lg")
      }
    } else if (status === "finished") {
      const n = state.number_of_winners || 3
      this.appendActionForm(this.topWinnersUrlValue, `Top ${n}`, "btn btn--pink btn--lg")
      this.appendActionForm(this.drawWinnersUrlValue, "Draw", "btn btn--light btn--lg")
      this.appendActionForm(this.resetWinnersUrlValue, "Reset winners", "btn btn--light btn--lg")
    }
  }

  renderLeaderboard(leaderboard) {
    this.leaderboardListTarget.replaceChildren()

    leaderboard.forEach((entry) => {
      const li = document.createElement("li")
      li.className = entry.winner ? "leader is-winner" : "leader"
      li.dataset.playerId = String(entry.id)

      const place = document.createElement("span")
      place.className = "leader__place"
      place.textContent = String(entry.place)
      li.appendChild(place)
      li.appendChild(document.createTextNode(" "))

      const name = document.createElement("span")
      name.className = "leader__name"
      name.appendChild(document.createTextNode(entry.name || ""))
      if (entry.winner) {
        name.appendChild(document.createTextNode(" "))
        const badge = document.createElement("span")
        badge.className = "leader__badge"
        badge.textContent = "Winner"
        name.appendChild(badge)
      }
      li.appendChild(name)
      li.appendChild(document.createTextNode(" "))

      const pts = entry.points ?? 0
      const score = document.createElement("span")
      score.className = "leader__score"
      score.textContent = entry.points_label || `${pts} ${pts === 1 ? "point" : "points"}`
      li.appendChild(score)

      this.leaderboardListTarget.appendChild(li)
    })
  }

  renderQuestionOptions(question, closed) {
    this.questionOptionsTarget.className = closed
      ? "stage-options stage-options--results"
      : "stage-options"
    this.questionOptionsTarget.replaceChildren()

    const totalAnswers = question.total_answers || 0

    question.options.forEach((opt, idx) => {
      const li = document.createElement("li")
      li.className = closed && opt.correct ? "stage-option is-correct" : "stage-option"

      if (closed) {
        const count = opt.answers_count || 0
        const share = totalAnswers > 0 ? Math.round((count / totalAnswers) * 100) : 0
        const bar = document.createElement("span")
        bar.className = "stage-option__bar"
        bar.style.setProperty("--share", `${share}%`)
        li.appendChild(bar)
      }

      const letter = document.createElement("span")
      letter.className = "stage-option__letter"
      letter.textContent = this.optionLetter(idx)
      li.appendChild(letter)
      li.appendChild(document.createTextNode(" "))

      const title = document.createElement("span")
      title.className = "stage-option__title"
      title.textContent = opt.text
      li.appendChild(title)

      if (closed) {
        if (opt.correct) {
          li.appendChild(document.createTextNode(" "))
          const mark = document.createElement("span")
          mark.className = "stage-option__mark"
          mark.textContent = "Correct"
          li.appendChild(mark)
        }

        li.appendChild(document.createTextNode(" "))
        const countEl = document.createElement("span")
        countEl.className = "stage-option__count"
        countEl.textContent = String(opt.answers_count ?? 0)
        li.appendChild(countEl)
      }

      this.questionOptionsTarget.appendChild(li)
    })
  }

  appendActionForm(actionUrl, label, buttonClass) {
    if (!actionUrl) return

    const form = document.createElement("form")
    form.setAttribute("action", actionUrl)
    form.setAttribute("method", "post")
    form.dataset.action = "submit->moderator-game#performAction"

    const csrf = this.csrfToken()
    if (csrf) {
      const tokenInput = document.createElement("input")
      tokenInput.type = "hidden"
      tokenInput.name = "authenticity_token"
      tokenInput.value = csrf
      form.appendChild(tokenInput)
    }

    const methodInput = document.createElement("input")
    methodInput.type = "hidden"
    methodInput.name = "_method"
    methodInput.value = "patch"
    form.appendChild(methodInput)

    const btn = document.createElement("button")
    btn.type = "submit"
    btn.className = buttonClass
    btn.textContent = label
    form.appendChild(btn)

    this.actionButtonsTarget.appendChild(form)
  }
}
