cat <<'EOF' > app/javascript/controllers/moderator_game_controller.js
import { Controller } from "@hotwired/stimulus"
import { createConsumer } from "@rails/actioncable"

export default class extends Controller {
  static values = {
    initialState: Object,
    streamToken: String,
    stateUrl: String,
    startUrl: String,
    finishUrl: String,
    nextUrl: String,
    endUrl: String,
    topWinnersUrl: String,
    drawWinnersUrl: String,
    resetWinnersUrl: String
  }

  static targets = [
    "topTitle",
    "lobbyView",
    "playersCounter",
    "questionView",
    "questionProgress",
    "questionTimer",
    "questionBody",
    "questionOptions",
    "finishedView",
    "leaderboardList",
    "controlsJoinUrl",
    "answersCounter",
    "actionButtons"
  ]

  connect() {
    this.state = { ...this.initialStateValue }
    this.lastVersion = typeof this.state.version === "number" ? this.state.version : -1
    this.renderedPhaseKey = this.phaseKey(this.state)
    this.renderedControlsKey = this.controlsKey(this.state)
    this.actionChain = Promise.resolve()
    this.cableConnected = false

    this.timerInterval = null
    this.autoFinishTimeout = null
    this.timerQuestionId = null
    this.timerDeadlineMs = null
    this.autoFinishSentForQuestionId = null

    this.syncTimerFromState(this.state)

    this.handleVisibilityChange = () => {
      if (document.visibilityState === "visible") {
        this.syncState()
      }
    }
    document.addEventListener("visibilitychange", this.handleVisibilityChange)

    this.consumer = createConsumer("/cable")
    this.subscription = this.consumer.subscriptions.create(
      {
        channel: "ModerateGameChannel",
        stream_token: this.streamTokenValue
      },
      {
        connected: () => {
          this.cableConnected = true
          this.syncState()
        },
        disconnected: () => {
          this.cableConnected = false
        },
        received: (data) => {
          this.applyState(data)
        }
      }
    )

    this.pollTimer = setInterval(() => {
      if (!this.cableConnected || this.state.status !== "finished") {
        this.syncState()
      }
    }, 2000)
  }

  disconnect() {
    document.removeEventListener("visibilitychange", this.handleVisibilityChange)
    this.stopTimer()
    if (this.pollTimer) {
      clearInterval(this.pollTimer)
      this.pollTimer = null
    }
    if (this.subscription) {
      this.subscription.unsubscribe()
      this.subscription = null
    }
    if (this.consumer) {
      this.consumer.disconnect()
      this.consumer = null
    }
  }

  phaseKey(state) {
    if (!state) return ""
    if (state.status === "finished") {
      const boardKey = (state.leaderboard || [])
        .map((entry) => `${entry.id}:${entry.place}:${entry.points}:${entry.winner ? 1 : 0}`)
        .join(",")
      return `finished:${state.number_of_winners || 0}:${boardKey}`
    }
    return `${state.status}:${state.question?.id || 0}`
  }

  controlsKey(state) {
    if (!state) return ""
    if (state.status === "finished") {
      return `finished:${state.number_of_winners || 0}`
    }
    return `${state.status}:${state.question?.id || 0}:${state.question?.last_question ? 1 : 0}`
  }

  optionLetter(index) {
    let n = index
    let result = ""
    while (n >= 0) {
      result = String.fromCharCode(65 + (n % 26)) + result
      n = Math.floor(n / 26) - 1
    }
    return result
  }

  formatTimerMs(ms) {
    const clampedMs = Math.max(0, Math.round(ms))
    const totalSeconds = Math.ceil(clampedMs / 1000)
    const minutes = Math.floor(totalSeconds / 60)
    const seconds = totalSeconds % 60
    return `${minutes}:${String(seconds).padStart(2, "0")}`
  }

  syncTimerFromState(state) {
    const question = state?.question
    if (state?.status === "question_open" && question && typeof question.timer_remaining_ms === "number") {
      const qId = question.id
      const candidateDeadline = performance.now() + question.timer_remaining_ms

      if (this.timerQuestionId !== qId || this.timerDeadlineMs === null) {
        this.timerQuestionId = qId
        this.timerDeadlineMs = candidateDeadline
        this.autoFinishSentForQuestionId = null
        if (this.autoFinishTimeout) {
          clearTimeout(this.autoFinishTimeout)
          this.autoFinishTimeout = null
        }
      } else if (Math.abs(candidateDeadline - this.timerDeadlineMs) > 250) {
        this.timerDeadlineMs = candidateDeadline
      }

      if (!this.timerInterval) {
        this.timerInterval = setInterval(() => this.tickTimer(), 100)
      }
      this.tickTimer()
    } else {
      this.stopTimer()
    }
  }

  tickTimer() {
    if (this.timerDeadlineMs === null || this.state?.status !== "question_open") {
      this.stopTimer()
      return
    }

    const remainingMs = Math.max(0, this.timerDeadlineMs - performance.now())
    const formatted = this.formatTimerMs(remainingMs)
    this.questionTimerTarget.hidden = false
    if (this.questionTimerTarget.textContent !== formatted) {
      this.questionTimerTarget.textContent = formatted
    }

    if (
      remainingMs <= 0 &&
      this.timerQuestionId != null &&
      this.autoFinishSentForQuestionId !== this.timerQuestionId
    ) {
      const expiringQuestionId = this.timerQuestionId
      this.autoFinishSentForQuestionId = expiringQuestionId
      if (this.autoFinishTimeout) clearTimeout(this.autoFinishTimeout)
      this.autoFinishTimeout = setTimeout(() => {
        this.autoFinishTimeout = null
        if (this.state?.status === "question_open" && this.state?.question?.id === expiringQuestionId) {
          this.triggerAutoFinish(expiringQuestionId)
        }
      }, 50)
    }
  }

  stopTimer() {
    if (this.timerInterval) {
      clearInterval(this.timerInterval)
      this.timerInterval = null
    }
    if (this.autoFinishTimeout) {
      clearTimeout(this.autoFinishTimeout)
      this.autoFinishTimeout = null
    }
    this.timerQuestionId = null
    this.timerDeadlineMs = null
    this.autoFinishSentForQuestionId = null
    if (this.hasQuestionTimerTarget) {
      this.questionTimerTarget.hidden = true
      this.questionTimerTarget.textContent = ""
    }
  }

  triggerAutoFinish(questionId) {
    if (!this.finishUrlValue) return
    const formData = new FormData()
    formData.append("_method", "patch")
    formData.append("question_id", String(questionId))

    this.actionChain = this.actionChain.then(async () => {
      if (this.state?.status !== "question_open" || this.state?.question?.id !== questionId) {
        return
      }
      try {
        const res = await fetch(this.finishUrlValue, {
          method: "POST",
          body: formData,
          credentials: "same-origin",
          headers: {
            "X-CSRF-Token": this.csrfToken(),
            "X-Quizzy-Async": "1",
            Accept: "application/json"
          }
        })
        if (res.ok) {
          const data = await res.json()
          this.applyState(data)
        }
      } catch (_err) {
        await this.syncState()
      }
    })
  }

  csrfToken() {
    return document.querySelector("meta[name='csrf-token']")?.content || ""
  }

  async syncState() {
    if (!this.stateUrlValue) return
    try {
      const res = await fetch(this.stateUrlValue, {
        method: "GET",
        credentials: "same-origin",
        headers: { Accept: "application/json" }
      })
      if (res.ok) {
        const data = await res.json()
        this.applyState(data)
      }
    } catch (_err) {
      // Ignore transient conference Wi-Fi errors; next poll/WS will recover
    }
  }

  performAction(event) {
    event.preventDefault()
    const form = event.currentTarget
    const actionUrl = form.getAttribute("action")
    const formData = new FormData(form)

    this.actionChain = this.actionChain.then(async () => {
      try {
        const res = await fetch(actionUrl, {
          method: "POST",
          body: formData,
          credentials: "same-origin",
          headers: {
            "X-CSRF-Token": this.csrfToken(),
            "X-Quizzy-Async": "1",
            Accept: "application/json"
          }
        })
        if (res.ok) {
          const data = await res.json()
          this.applyState(data)
        }
      } catch (_err) {
        await this.syncState()
      }
    })
  }

  applyState(nextState) {
    if (!nextState || !nextState.status) return
    if (typeof nextState.version === "number" && nextState.version < this.lastVersion) {
      return
    }
    if (typeof nextState.version === "number") {
      this.lastVersion = nextState.version
    }

    this.state = nextState

    const nextKey = this.phaseKey(nextState)
    if (nextKey !== this.renderedPhaseKey) {
      this.renderPhase(nextState)
      this.renderedPhaseKey = nextKey
    } else {
      this.updateLiveCounters(nextState)
    }
  }

  updateLiveCounters(state) {
    if (state.status === "lobby") {
      this.playersCounterTarget.textContent = `Players: ${state.active_players_count ?? 0}`
    } else if (state.status === "question_open" && state.question) {
      const answered = state.question.answered_count ?? 0
      const active = state.active_players_count ?? 0
      this.answersCounterTarget.textContent = `Answers: ${answered} / ${active}`
      this.syncTimerFromState(state)
    }
  }

  renderPhase(state) {
    const status = state.status
    const question = state.question

    if (status === "lobby") {
      this.element.className = "cover cover--blue"
    } else if (status === "question_open") {
      this.element.className = "cover cover--blue cover--calm"
    } else if (status === "question_closed") {
      this.element.className = "cover cover--night cover--calm"
    } else {
      this.element.className = "cover cover--night"
    }

    this.topTitleTarget.textContent = status === "lobby" ? "" : (state.quiz_title || "")

    this.lobbyViewTarget.hidden = status !== "lobby"
    this.questionViewTarget.hidden = !(status === "question_open" || status === "question_closed")
    this.finishedViewTarget.hidden = status !== "finished"

    this.controlsJoinUrlTarget.hidden = !(status === "question_open" || status === "question_closed")
    if (state.join_url) {
      this.controlsJoinUrlTarget.textContent = state.join_url
    }

    this.syncTimerFromState(state)

    if (status === "lobby") {
      this.playersCounterTarget.textContent = `Players: ${state.active_players_count ?? 0}`
      this.answersCounterTarget.hidden = true
      this.answersCounterTarget.textContent = ""
    } else if (status === "question_open" && question) {
      this.questionProgressTarget.textContent = `Question ${question.position} of ${question.total}`
      this.questionBodyTarget.textContent = question.body
      this.renderQuestionOptions(question, false)

      const answered = question.answered_count ?? 0
      const active = state.active_players_count ?? 0
      this.answersCounterTarget.hidden = false
      this.answersCounterTarget.textContent = `Answers: ${answered} / ${active}`
    } else if (status === "question_closed" && question) {
      this.questionProgressTarget.textContent = `Question ${question.position} of ${question.total}`
      this.questionBodyTarget.textContent = question.body
      this.renderQuestionOptions(question, true)

      this.answersCounterTarget.hidden = true
      this.answersCounterTarget.textContent = ""
    } else {
      this.answersCounterTarget.hidden = true
      this.answersCounterTarget.textContent = ""
      this.renderLeaderboard(state.leaderboard || [])
    }

    const nextControlsKey = this.controlsKey(state)
    if (nextControlsKey !== this.renderedControlsKey) {
      this.renderControls(state)
      this.renderedControlsKey = nextControlsKey
    }
  }

  renderControls(state) {
    const status = state.status
    const question = state.question
    this.actionButtonsTarget.replaceChildren()

    if (status === "lobby") {
      this.appendActionForm(this.startUrlValue, "Start", "btn btn--pink btn--lg")
    } else if (status === "question_open" && question) {
      this.appendActionForm(this.finishUrlValue, "Finish", "btn btn--pink btn--lg", {
        question_id: String(question.id)
      })
    } else if (status === "question_closed" && question) {
      if (question.last_question) {
        this.appendActionForm(this.endUrlValue, "End quiz", "btn btn--pink btn--lg")
      } else {
        this.appendActionForm(this.nextUrlValue, "Next", "btn btn--pink btn--lg")
      }
    } else if (status === "finished") {
      const n = state.number_of_winners || 3
      this.appendActionForm(this.topWinnersUrlValue, `Top ${n}`, "btn btn--pink btn--lg")
      this.appendActionForm(this.drawWinnersUrlValue, "Draw", "btn btn--light btn--lg")
      this.appendActionForm(this.resetWinnersUrlValue, "Reset winners", "btn btn--light btn--lg")
    }
  }

  renderLeaderboard(leaderboard) {
    this.leaderboardListTarget.replaceChildren()

    leaderboard.forEach((entry) => {
      const li = document.createElement("li")
      li.className = entry.winner ? "leader is-winner" : "leader"
      li.dataset.playerId = String(entry.id)

      const place = document.createElement("span")
      place.className = "leader__place"
      place.textContent = String(entry.place)
      li.appendChild(place)
      li.appendChild(document.createTextNode(" "))

      const name = document.createElement("span")
      name.className = "leader__name"
      name.appendChild(document.createTextNode(entry.name || ""))
      if (entry.winner) {
        name.appendChild(document.createTextNode(" "))
        const badge = document.createElement("span")
        badge.className = "leader__badge"
        badge.textContent = "Winner"
        name.appendChild(badge)
      }
      li.appendChild(name)
      li.appendChild(document.createTextNode(" "))

      const pts = entry.points ?? 0
      const score = document.createElement("span")
      score.className = "leader__score"
      score.textContent = entry.points_label || `${pts} ${pts === 1 ? "point" : "points"}`
      li.appendChild(score)

      this.leaderboardListTarget.appendChild(li)
    })
  }

  renderQuestionOptions(question, closed) {
    this.questionOptionsTarget.className = closed
      ? "stage-options stage-options--results"
      : "stage-options"
    this.questionOptionsTarget.replaceChildren()

    const totalAnswers = question.total_answers || 0

    question.options.forEach((opt, idx) => {
      const li = document.createElement("li")
      li.className = closed && opt.correct ? "stage-option is-correct" : "stage-option"

      if (closed) {
        const count = opt.answers_count || 0
        const share = totalAnswers > 0 ? Math.round((count / totalAnswers) * 100) : 0
        const bar = document.createElement("span")
        bar.className = "stage-option__bar"
        bar.style.setProperty("--share", `${share}%`)
        li.appendChild(bar)
      }

      const letter = document.createElement("span")
      letter.className = "stage-option__letter"
      letter.textContent = this.optionLetter(idx)
      li.appendChild(letter)
      li.appendChild(document.createTextNode(" "))

      const title = document.createElement("span")
      title.className = "stage-option__title"
      title.textContent = opt.text
      li.appendChild(title)

      if (closed) {
        if (opt.correct) {
          li.appendChild(document.createTextNode(" "))
          const mark = document.createElement("span")
          mark.className = "stage-option__mark"
          mark.textContent = "Correct"
          li.appendChild(mark)
        }

        li.appendChild(document.createTextNode(" "))
        const countEl = document.createElement("span")
        countEl.className = "stage-option__count"
        countEl.textContent = String(opt.answers_count ?? 0)
        li.appendChild(countEl)
      }

      this.questionOptionsTarget.appendChild(li)
    })
  }

  appendActionForm(actionUrl, label, buttonClass, extraParams = {}) {
    if (!actionUrl) return

    const form = document.createElement("form")
    form.setAttribute("action", actionUrl)
    form.setAttribute("method", "post")
    form.dataset.action = "submit->moderator-game#performAction"

    const csrf = this.csrfToken()
    if (csrf) {
      const tokenInput = document.createElement("input")
      tokenInput.type = "hidden"
      tokenInput.name = "authenticity_token"
      tokenInput.value = csrf
      form.appendChild(tokenInput)
    }

    const methodInput = document.createElement("input")
    methodInput.type = "hidden"
    methodInput.name = "_method"
    methodInput.value = "patch"
    form.appendChild(methodInput)

    Object.entries(extraParams).forEach(([key, value]) => {
      const hiddenInput = document.createElement("input")
      hiddenInput.type = "hidden"
      hiddenInput.name = key
      hiddenInput.value = value
      form.appendChild(hiddenInput)
    })

    const btn = document.createElement("button")
    btn.type = "submit"
    btn.className = buttonClass
    btn.textContent = label
    form.appendChild(btn)

    this.actionButtonsTarget.appendChild(form)
  }
}
EOF

